async def act(page):
    # From the current Order View page, the billing address Edit link points to:
    # /index.php/admin/sales_order/address/address_id/868/
    # We'll navigate there using a relative goto, update the address to
    # 789 Pine Lane, San Francisco, CA, 94102 and click Save (making the Save the last
    # interactive action).

    # No knowledge_base helper functions are available or applicable for this task.

    # Navigate to billing address edit page
    await page.goto("/index.php/admin/sales_order/address/address_id/868/")
    await page.wait_for_load_state("networkidle")

    # Helper to attempt filling a field by several possible label names
    async def try_fill(labels, value):
        for lbl in labels:
            try:
                await page.get_by_label(lbl).fill(value)
                return True
            except Exception:
                continue
        return False

    # Fill Street
    await try_fill(["Street Address", "Street 1", "Street", "Address", "Address 1"], "789 Pine Lane")

    # Fill City
    await try_fill(["City", "Town/City"], "San Francisco")

    # Select Region/State (try label then value)
    region_labels = ["State/Province", "Region", "State"]
    for rlbl in region_labels:
        try:
            elm = page.get_by_label(rlbl)
            try:
                await elm.select_option(label="California")
                break
            except Exception:
                try:
                    await elm.select_option(value="CA")
                    break
                except Exception:
                    continue
        except Exception:
            continue

    # Fill Postal Code
    await try_fill(["Zip/Postal Code", "ZIP/Postal Code", "ZIP Code", "Postal Code", "Postcode"], "94102")

    # Ensure Country is United States if a country select exists
    try:
        await page.get_by_label("Country").select_option(label="United States")
    except Exception:
        try:
            await page.get_by_label("Country").select_option(value="US")
        except Exception:
            pass

    # Click Save (make this the last interactive action). Prefer scoped selection via form.
    save_clicked = False
    save_names = ["Save Address", "Save", "Save Changes"]
    for name in save_names:
        try:
            try:
                await page.get_by_role("form").get_by_role("button", name=name).click()
            except Exception:
                await page.get_by_role("button", name=name).click()
            save_clicked = True
            break
        except Exception:
            continue

    # If no explicit save button was found, press Enter in the City field as a fallback (still last action)
    if not save_clicked:
        try:
            await page.get_by_label("City").press("Enter")
        except Exception:
            pass
